    select
        hospital.spine_key,
        (hospital.window_start::timestamp) at time zone 'UTC' as event_timestamp
    from {{ ref('int_hospital_spine') }} as hospital
),

measures as (
    select
        measures.spine_key,
        measures.value_category,
        measures.value_number,
        measures.measure_control || '|' || measures.field as pivot_key
    from {{ ref('int_spine_care_compare_measures') }} as measures
),

pivoted as (
